    23	export const makeCharRule = (
    24	  ruleDef: InternalRuleDefChar | InternalRuleDefCharNot,
    25	): RuleChar | RuleCharExclude => {
    26	  if (isRuleDefCharNot(ruleDef)) {
    27	    return new RuleCharExclude(ruleDef.value);
    28	  }
    29	  if (isRuleDefChar(ruleDef)) {
    30	    return new RuleChar(ruleDef.value);
    31	  }
    32	
    33	  throw new Error(`Unsupported rule type for make_char_rule: ${JSON.stringify(ruleDef)}`);
    34	};
    35	
    36	export const buildRuleStack = (linearRules: InternalRuleDef[]): UnresolvedRule[][] => {
    37	  let paths: UnresolvedRule[] = [];
    38	  const stack: UnresolvedRule[][] = [];
    39	  let idx = 0;
    40	
    41	  while (idx < linearRules.length) {
    42	    const ruleDef = linearRules[idx];
    43	    if (isRuleDefChar(ruleDef) || isRuleDefCharNot(ruleDef)) {
    44	      // this could be a single char, or a range, or a sequence of alts;
    45	      // we don't know until we step through it.
    46	      const charRule = makeCharRule(ruleDef);
    47	      idx += 1;
    48	      let rule: InternalRuleDef | undefined = linearRules[idx];
    49	      while (idx < linearRules.length && (isRuleDefCharRngUpper(rule) || isRuleDefCharAlt(rule))) {
    50	        if (isRuleDefCharRngUpper(rule)) {
    51	          // previous rule value should be a number
    52	          const prevValue = charRule.value.pop();
    53	          if (isRange(prevValue)) {
    54	            throw new Error(
    55	              `Unexpected range, expected a number but got an array: ${JSON.stringify(prevValue)}`,
    56	            );
    57	          }
    58	          if (prevValue === undefined) {
    59	            throw new Error('Unexpected undefined value');
    60	          }
    61	
    62	          charRule.value.push([prevValue, rule.value] as Range);
    63	        }
    64	        if (isRuleDefCharAlt(rule)) {
    65	          charRule.value.push(rule.value);
    66	        }
    67	        idx += 1;
    68	        rule = linearRules[idx];
    69	      }
    70	      paths.push(charRule);
    71	    } else {
    72	      if (isRuleDefAlt(ruleDef)) {
    73	        if (paths.length === 0) {
    74	          throw new Error('Encountered alt without anything before it');
    75	        }
    76	        paths.push(new RuleEnd());
    77	        stack.push(paths);
    78	        paths = [];
    79	      } else if (isRuleDefEnd(ruleDef)) {
    80	        paths.push(new RuleEnd());
    81	      } else if (isRuleDefRef(ruleDef)) {
    82	        paths.push(new RuleRef(ruleDef.value));
    83	      } else if (isRuleDefCharAlt(ruleDef)) {
    84	        throw new Error(
    85	          `Encountered char alt, should be handled by above block: ${JSON.stringify(ruleDef)}`,
    86	        );
    87	      } else {
    88	        throw new Error(`Unsupported rule type: ${JSON.stringify(ruleDef)}`);
    89	      }
    90	      idx += 1;
    91	    }
    92	  }
    93	
    94	  if (!isRuleEnd(paths[paths.length - 1])) {
    95	    paths.push(new RuleEnd());
    96	  }
    97	
    98	  stack.push(paths);
    99	  return stack;
