    11	export const parseChar = (src: string, pos: number): [number, number] => {
    12	  if (pos >= src.length) {
    13	    throw new GrammarParseError(
    14	      src,
    15	      pos,
    16	      'Unexpected end of grammar input, failed to complete parse',
    17	    );
    18	  }
    19	
    20	  if (src[pos] === '\\') {
    21	    const next = src[pos + 1];
    22	    if (next === 'x') {
    23	      return [parseInt(src.slice(pos + 2, pos + 4), 16), 4];
    24	    }
    25	    if (next === 'u') {
    26	      return [parseInt(src.slice(pos + 2, pos + 6), 16), 6];
    27	    }
    28	    if (next === 'U') {
    29	      return [parseInt(src.slice(pos + 2, pos + 10), 16), 10];
    30	    }
    31	    if (next in ESCAPE_CHARS) {
    32	      return [ESCAPE_CHARS[next], 2];
    33	    }
    34	    if (LITERAL_ESCAPES.includes(next)) {
    35	      return [next.codePointAt(0) as number, 2];
    36	    }
    37	    throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
    38	  }
    39	
    40	  return [src.codePointAt(pos) as number, 1];
    41	};
